(function($){if(!window.contactinDashboardWidgets){return;}var config=window.contactinDashboardWidgets;var timer=null;var statusLabels={good:"System Healthy",warning:"System Warning",error:"System Issues"};function setText(selector,value){var el=document.querySelector(selector);if(!el){return;}el.textContent=value;}function setHtml(selector,value){var el=document.querySelector(selector);if(!el){return;}el.innerHTML=value;}function updateStatusClass(el,status){if(!el){return;}var classes=el.className.split(" ");var kept=[];for(var i=0;i<classes.length;i++){if(classes[i].indexOf("status-")!==0){kept.push(classes[i]);}}el.className=kept.join(" ");if(status){el.classList.add("status-"+status);} }function statusIcon(status){switch(status){case"good":case"healthy":return"✓";case"warning":return"⚠";case"error":case"critical":return"✗";default:return"–";}}function formatPercent(value){var num=parseFloat(value||0);return num.toFixed(1)+"%";}function updatePerformance(data){if(!data){return;}setText('[data-cin-perf="crm-rate"]',formatPercent(data.crm&&data.crm.rate));setText('[data-cin-perf="crm-message"]',data.crm&&data.crm.message?data.crm.message:"");setText('[data-cin-perf="crm-successful"]',(data.crm&&data.crm.successful)||0);setText('[data-cin-perf="crm-failed"]',(data.crm&&data.crm.failed)||0);setText('[data-cin-perf="crm-pending"]',(data.crm&&data.crm.pending)||0);setText('[data-cin-perf="crm-total"]',(data.crm&&data.crm.total)||0);var crmStatus=document.querySelector('[data-cin-perf-status="crm"]');updateStatusClass(crmStatus,data.crm&&data.crm.status);setText('[data-cin-perf="queue-pending"]',(data.queue&&data.queue.pending)||0);setText('[data-cin-perf="queue-message"]',data.queue&&data.queue.message?data.queue.message:"");var queueStatus=document.querySelector('[data-cin-perf-status="queue"]');updateStatusClass(queueStatus,data.queue&&data.queue.status);setText('[data-cin-perf="email-rate"]',formatPercent(data.email&&data.email.rate));setText('[data-cin-perf="email-message"]',data.email&&data.email.message?data.email.message:"");var emailStatus=document.querySelector('[data-cin-perf-status="email"]');updateStatusClass(emailStatus,data.email&&data.email.status);var apiValue=0;if(data.api){apiValue=(typeof data.api.time_ms!=="undefined")?data.api.time_ms:(data.api.total_requests||0);}setText('[data-cin-perf="api-time"]',apiValue);setText('[data-cin-perf="api-message"]',data.api&&data.api.message?data.api.message:"");var apiStatus=document.querySelector('[data-cin-perf-status="api"]');updateStatusClass(apiStatus,data.api&&data.api.status);var systemStatus=data.system_status||"good";var systemWrap=document.querySelector('[data-cin-perf="system-status"]');if(systemWrap){updateStatusClass(systemWrap,systemStatus);}var systemIndicator=document.querySelector('[data-cin-perf-status="system"]');updateStatusClass(systemIndicator,systemStatus);setText('[data-cin-perf="system-status-label"]',statusLabels[systemStatus]||"System Status");}
function updateIntegration(data){if(!data){return;}var crmStatusBadge=document.querySelector('[data-cin-integration="crm-status"]');updateStatusClass(crmStatusBadge,data.crm&&data.crm.status);setText('[data-cin-integration="crm-status"]',statusIcon(data.crm&&data.crm.status));setText('[data-cin-integration="crm-rate"]',formatPercent(data.crm&&data.crm.rate));setText('[data-cin-integration="crm-message"]',data.crm_health&&data.crm_health.message?data.crm_health.message:"Unknown");var emailStatusBadge=document.querySelector('[data-cin-integration="email-status"]');updateStatusClass(emailStatusBadge,data.email&&data.email.status);setText('[data-cin-integration="email-status"]',statusIcon(data.email&&data.email.status));setText('[data-cin-integration="email-rate"]',formatPercent(data.email&&data.email.rate));setText('[data-cin-integration="email-message"]',data.email&&data.email.message?data.email.message:"");var apiStatusBadge=document.querySelector('[data-cin-integration="api-status"]');updateStatusClass(apiStatusBadge,data.api&&data.api.status);setText('[data-cin-integration="api-status"]',statusIcon(data.api&&data.api.status));setText('[data-cin-integration="api-health"]',data.api&&data.api.status?data.api.status.charAt(0).toUpperCase()+data.api.status.slice(1):"Unknown");var apiRequests=0;if(data.api){apiRequests=(typeof data.api.time_ms!=="undefined")?data.api.time_ms:(data.api.total_requests||0);}setText('[data-cin-integration="api-requests"]',apiRequests);}function updateSnapshot(data){if(!data){return;}setText('[data-cin-snapshot="total-submissions"]',data.total_submissions||0);setText('[data-cin-snapshot="completed-count"]',data.completed||0);setText('[data-cin-snapshot="failed-count"]',data.failed||0);var completedBar=document.querySelector('[data-cin-snapshot="completed-bar"]');if(completedBar){completedBar.style.width=(data.completed_pct||0)+"%";}var failedBar=document.querySelector('[data-cin-snapshot="failed-bar"]');if(failedBar){failedBar.style.width=(data.failed_pct||0)+"%";}var healthBadge=document.querySelector('[data-cin-snapshot="system-health"]');updateStatusClass(healthBadge,(data.system_health||"good").toLowerCase());var label=statusLabels[data.system_health||"good"]||"System Status";setText('[data-cin-snapshot="system-health-label"]',label);}function updateSubmissions(data){if(!data){return;}setText('[data-cin-submissions="today-count"]',data.today_count||0);setText('[data-cin-submissions="conversion-rate"]',formatPercent(data.conversion_rate||0));setText('[data-cin-submissions="completed-count"]',data.completed||0);setText('[data-cin-submissions="failed-count"]',data.failed||0);setText('[data-cin-submissions="completion-rate"]',(data.completion_rate||0)+"%");}
function fetchWidgets(){if(!config.ajax_url||!config.nonce){return;}$.post(config.ajax_url,{action:"contactin_get_dashboard_widgets",nonce:config.nonce},function(resp){if(!resp||!resp.success||!resp.data){return;}updateSnapshot(resp.data.snapshot);updateSubmissions(resp.data.submissions);updatePerformance(resp.data.performance);updateIntegration(resp.data.integration);});}
$(function(){fetchWidgets();if(timer){clearInterval(timer);}timer=setInterval(fetchWidgets,config.refresh_ms||30000);});})(jQuery);